/**
 * Diagnostic agent — ONE job: a short placement SELF-CHECK before a roadmap is built.
 *
 *  - createDiagnostic({exam, level}): 12 ORIGINAL multiple-choice questions (2 each: listening
 *    [transcript given as text], reading, grammar, vocabulary, writing-awareness, speaking-awareness)
 *    in the exam's target language, calibrated around `level` with a spread one band below/above.
 *    Generated by the LLM (agent DIAGNOSTIC), strictly validated, cached as 3 rotating variants in
 *    public/data/practice_sets/diagnostic-{EXAM}-{LEVEL}.
 *  - scoreDiagnostic({exam, level, answers}): deterministic (no LLM). Per-skill scores 0..1,
 *    estimatedLevel = highest CEFR band with >= 60% correct, short advice strings.
 *
 * This is NOT an official placement test; every response says so.
 * @module lib/agents/diagnostic
 */
import {
  LEVELS, EXAM_LANG, LANG_NAME, LEARNER_SKILLS, DISCLAIMER, BadInput,
  parseExam, parseLevel, clean, hasUrl, looksLike, deps, setLearnerDeps
} from './learnerShared.js';
import { THETA, scoreFixed, pCorrect } from '../algo/placement.js';

export { setLearnerDeps as __setTestDeps };

export const VARIANTS = 3;
export const QUESTIONS_PER_SKILL = 2;
export const PASS_RATIO = 0.6;
export const SELF_CHECK_NOTICE =
  'Self-check only — this is not an official placement test and does not predict an exam result. ' + DISCLAIMER;

/** CEFR bands a quiz for `level` may use: one below, the level itself, one above (clipped to A1..C2). */
export function bandsFor(level) {
  const i = LEVELS.indexOf(level);
  return { below: LEVELS[i - 1] || null, at: level, above: LEVELS[i + 1] || null };
}

const QUESTION_SCHEMA = {
  type: 'object',
  properties: {
    id: { type: 'string' },
    skill: { type: 'string', enum: LEARNER_SKILLS },
    transcript: { type: 'string', description: 'listening only: the short text the learner would hear' },
    prompt: { type: 'string' },
    options: { type: 'array', items: { type: 'string' }, minItems: 4, maxItems: 4 },
    answerIndex: { type: 'integer', minimum: 0, maximum: 3 },
    explanation: { type: 'string' },
    cefr: { type: 'string', enum: LEVELS }
  },
  required: ['id', 'skill', 'prompt', 'options', 'answerIndex', 'explanation', 'cefr']
};
const SCHEMA = {
  type: 'object',
  properties: { questions: { type: 'array', items: QUESTION_SCHEMA, minItems: 12, maxItems: 12 } },
  required: ['questions']
};

const normOpt = (s) => clean(s).toLowerCase().replace(/[\s.,;:!?¡¿"'«»„“”]+$/g, '');

/**
 * Strict validator for LLM output (returns an error string fed back to the LLM, or null).
 * Exported for tests.
 */
export function validateDiagnostic(data, { exam, level }) {
  const lang = EXAM_LANG[exam];
  const bands = bandsFor(level);
  const allowed = new Set(Object.values(bands).filter(Boolean));
  const qs = data?.questions;
  if (!Array.isArray(qs)) return 'Top-level "questions" array is missing.';
  if (qs.length !== LEARNER_SKILLS.length * QUESTIONS_PER_SKILL) return `Need exactly ${LEARNER_SKILLS.length * QUESTIONS_PER_SKILL} questions, got ${qs.length}.`;
  const perSkill = {};
  const perBand = {};
  const ids = new Set();
  let allText = '';
  for (const [i, q] of qs.entries()) {
    const at = `questions[${i}]`;
    if (!q || typeof q !== 'object') return `${at} is not an object.`;
    if (typeof q.id !== 'string' || !q.id.trim()) return `${at}.id must be a non-empty string.`;
    if (ids.has(q.id)) return `Duplicate id "${q.id}".`;
    ids.add(q.id);
    if (!LEARNER_SKILLS.includes(q.skill)) return `${at}.skill must be one of ${LEARNER_SKILLS.join(', ')}.`;
    perSkill[q.skill] = (perSkill[q.skill] || 0) + 1;
    if (typeof q.prompt !== 'string' || clean(q.prompt).length < 5) return `${at}.prompt is missing or too short.`;
    if (!Array.isArray(q.options) || q.options.length !== 4) return `${at}.options must have exactly 4 entries.`;
    if (q.options.some((o) => typeof o !== 'string' || !clean(o))) return `${at}.options must be non-empty strings.`;
    if (new Set(q.options.map(normOpt)).size !== 4) return `${at}.options contain duplicates.`;
    if (!Number.isInteger(q.answerIndex) || q.answerIndex < 0 || q.answerIndex > 3) return `${at}.answerIndex must be an integer 0..3.`;
    if (typeof q.explanation !== 'string' || !clean(q.explanation)) return `${at}.explanation is missing.`;
    if (!allowed.has(q.cefr)) return `${at}.cefr must be one of ${[...allowed].join(', ')}.`;
    perBand[q.cefr] = (perBand[q.cefr] || 0) + 1;
    if (q.skill === 'listening') {
      if (typeof q.transcript !== 'string' || clean(q.transcript).split(' ').length < 12)
        return `${at} is a listening item: "transcript" must hold the short spoken text (at least 12 words).`;
      if (!looksLike(q.transcript, lang)) return `${at}.transcript must be in ${LANG_NAME[lang]}.`;
    }
    if (!looksLike(q.prompt, lang)) return `${at}.prompt must be written in ${LANG_NAME[lang]}.`;
    if ([q.prompt, q.transcript, q.explanation, ...q.options].some((s) => s && hasUrl(s))) return `${at} must not contain URLs or website names.`;
    allText += ` ${q.transcript || ''} ${q.prompt} ${q.options.join(' ')}`;
  }
  for (const s of LEARNER_SKILLS) if (perSkill[s] !== QUESTIONS_PER_SKILL) return `Need exactly ${QUESTIONS_PER_SKILL} "${s}" questions, got ${perSkill[s] || 0}.`;
  if ((perBand[bands.at] || 0) < 4) return `At least 4 questions must be at ${bands.at}.`;
  for (const b of [bands.below, bands.above].filter(Boolean)) if ((perBand[b] || 0) < 2) return `At least 2 questions must be at ${b} (spread one level below and above).`;
  if (!looksLike(allText, lang, 1)) return `Questions must be in ${LANG_NAME[lang]}, the language of ${exam}.`;
  return null;
}

function normalizeQuestions(qs) {
  return qs.map((q, i) => ({
    id: `q${i + 1}`,
    skill: q.skill,
    ...(q.skill === 'listening' ? { transcript: clean(q.transcript, 1500) } : {}),
    prompt: clean(q.prompt, 1200),
    options: q.options.map((o) => clean(o, 300)),
    answerIndex: q.answerIndex,
    explanation: clean(q.explanation, 600),
    cefr: q.cefr
  }));
}

function systemPrompt(exam, level) {
  const lang = LANG_NAME[EXAM_LANG[exam]];
  const b = bandsFor(level);
  return [
    `You write ORIGINAL placement self-check questions for learners preparing the ${exam} (${lang}).`,
    'Never reproduce, translate or paraphrase items from official exams, sample papers or textbooks; invent new content.',
    `Write every transcript, prompt and option in ${lang}. The explanation may be short and simple ${lang}.`,
    'Never include URLs, website names or claims about the official exam format.',
    `Calibrate around CEFR ${level}: at least 4 questions at ${level}` +
      (b.below ? `, at least 2 at ${b.below}` : '') + (b.above ? `, at least 2 at ${b.above}` : '') + '. Set "cefr" honestly per question.',
    'Exactly 12 multiple-choice questions, 2 per skill:',
    '- listening: put a short spoken text (2–5 sentences, a dialogue or announcement) in "transcript"; the prompt asks about it.',
    '- reading: a short text inside the prompt, then a question about it.',
    '- grammar: a gap-fill or form choice.',
    '- vocabulary: meaning / word choice in context.',
    '- writing (writing-awareness): pick the most appropriate sentence/register/connector for a written task.',
    '- speaking (speaking-awareness): pick the most natural spoken reply in a given situation.',
    'Each question: exactly 4 distinct options, one correct, answerIndex 0..3 (vary the position).'
  ].join('\n');
}

const docKey = (exam, level) => `diagnostic-${exam}-${level}`;

/** Ask the LLM for one fresh validated variant. */
async function generateVariant(d, exam, level) {
  const { data, model } = await d.generateJson({
    agent: 'DIAGNOSTIC',
    system: systemPrompt(exam, level),
    prompt: `Create the 12-question ${exam} self-check around ${level}. Return {"questions":[...]}.`,
    schema: SCHEMA,
    temperature: 0.7,
    validate: (x) => validateDiagnostic(x, { exam, level })
  });
  return { questions: normalizeQuestions(data.questions), model: model || null };
}

/**
 * Attach an IRT difficulty `b` to every question: the calibrated value from
 * item_sets/{EXAM}_{LEVEL} (written by the nightly calibration fold) when present, else the CEFR
 * band's anchor THETA[cefr]. Best effort: a read failure falls back to the anchors.
 */
async function withDifficulty(d, exam, level, questions) {
  let calibrated = {};
  try {
    const snap = await d.pub().collection('item_sets').doc(`${exam}_${level}`).get();
    if (snap.exists) calibrated = snap.data()?.b || {};
  } catch {
    /* anchors only */
  }
  return questions.map((q) => {
    const cal = calibrated[itemKey(exam, level, q)];
    return { ...q, itemKey: itemKey(exam, level, q), b: typeof cal === 'number' && Number.isFinite(cal) ? cal : THETA[q.cefr] ?? 0 };
  });
}

/** Stable per-item id for calibration: exam, level, CEFR band and a hash of the prompt. */
export function itemKey(exam, level, q) {
  let h = 0x811c9dc5;
  const s = `${exam}|${level}|${q.prompt || ''}`;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 0x01000193) >>> 0;
  return `${q.cefr || 'x'}_${h.toString(16).padStart(8, '0')}`;
}

/**
 * Returns { status:'ok', quizId, exam, level, questions, notice, source } or
 * { status:'failed', error } when no variant exists and the LLM is unavailable.
 */
export async function createDiagnostic(input) {
  const exam = parseExam(input?.exam);
  const level = parseLevel(input?.level);
  const d = await deps();
  const ref = d.pub().collection('practice_sets').doc(docKey(exam, level));
  const snap = await ref.get();
  const doc = snap.exists ? snap.data() : {};
  const variants = Array.isArray(doc.variants) ? doc.variants : [];

  const serve = async (source, note) => {
    const idx = (Number(doc.nextIndex) || 0) % variants.length;
    await ref.set({ nextIndex: idx + 1 }, { merge: true });
    const v = variants[idx];
    return { status: 'ok', quizId: v.quizId, exam, level, mode: 'fixed', questions: await withDifficulty(d, exam, level, v.questions), notice: SELF_CHECK_NOTICE, source, ...(note ? { note } : {}) };
  };

  if (variants.length >= VARIANTS) return serve('cache');

  try {
    const v = await generateVariant(d, exam, level);
    const quizId = `${docKey(exam, level)}-v${variants.length + 1}`;
    const entry = { quizId, questions: v.questions, model: v.model, createdAt: d.now().toISOString() };
    await ref.set({ kind: 'diagnostic', exam, level, variants: [...variants, entry].slice(0, VARIANTS), updatedAt: entry.createdAt }, { merge: true });
    return { status: 'ok', quizId, exam, level, mode: 'fixed', questions: await withDifficulty(d, exam, level, v.questions), notice: SELF_CHECK_NOTICE, source: 'live' };
  } catch (err) {
    if (variants.length) return serve('cache', 'Live generation unavailable; served a cached quiz.');
    return { status: 'failed', error: `Diagnostic generation unavailable: ${clean(err?.message || String(err), 200)}` };
  }
}

// ---------- deterministic scoring ----------
const round2 = (x) => Math.round(x * 100) / 100;
const SKILL_TIPS = {
  listening: 'daily short audio (news, podcasts) with transcripts, then re-listen without them',
  reading: 'one short article a day, summarise it in 3 sentences',
  grammar: 'targeted drills on the structures you missed, 15 minutes a day',
  vocabulary: 'a themed word list with spaced repetition, 10 new words a day',
  writing: 'one short timed text every two days, checked against a task checklist',
  speaking: 'record yourself answering a prompt for 2 minutes, then self-correct'
};

function parseAnswers(raw) {
  if (!Array.isArray(raw) || raw.length < 1 || raw.length > 50) throw new BadInput('answers must be an array of 1..50 items');
  return raw.map((a, i) => {
    if (!a || typeof a !== 'object') throw new BadInput(`answers[${i}] must be an object`);
    if (!LEARNER_SKILLS.includes(a.skill)) throw new BadInput(`answers[${i}].skill must be one of ${LEARNER_SKILLS.join(', ')}`);
    if (typeof a.correct !== 'boolean') throw new BadInput(`answers[${i}].correct must be boolean`);
    if (a.cefr !== undefined && a.cefr !== null && !LEVELS.includes(a.cefr)) throw new BadInput(`answers[${i}].cefr must be A1..C2`);
    if (a.id !== undefined && (typeof a.id !== 'string' || a.id.length > 80)) throw new BadInput(`answers[${i}].id must be a short string`);
    if (a.itemKey !== undefined && (typeof a.itemKey !== 'string' || !/^[A-Za-z0-9_-]{1,40}$/.test(a.itemKey))) throw new BadInput(`answers[${i}].itemKey must be a short id`);
    if (a.b !== undefined && (typeof a.b !== 'number' || !Number.isFinite(a.b) || Math.abs(a.b) > 6)) throw new BadInput(`answers[${i}].b must be a number in [-6, 6]`);
    return { id: a.id ?? `a${i + 1}`, skill: a.skill, correct: a.correct, cefr: a.cefr || null, ...(a.itemKey ? { itemKey: a.itemKey } : {}), ...(typeof a.b === 'number' ? { b: a.b } : {}) };
  });
}

/** Deterministic, no LLM. Returns { skillScores, bandScores, estimatedLevel, method, advice, notice }. */
export function scoreDiagnostic(input) {
  const exam = parseExam(input?.exam);
  const level = parseLevel(input?.level);
  const answers = parseAnswers(input?.answers);

  const tally = (keyFn) => {
    const t = {};
    for (const a of answers) {
      const k = keyFn(a);
      if (!k) continue;
      t[k] ||= { correct: 0, total: 0 };
      t[k].total++;
      if (a.correct) t[k].correct++;
    }
    return t;
  };
  const bySkill = tally((a) => a.skill);
  const byBand = tally((a) => a.cefr);
  const skillScores = Object.fromEntries(Object.entries(bySkill).map(([k, v]) => [k, round2(v.correct / v.total)]));
  const bandScores = Object.fromEntries(
    LEVELS.filter((l) => byBand[l]).map((l) => [l, { ...byBand[l], ratio: round2(byBand[l].correct / byBand[l].total) }])
  );

  let estimatedLevel;
  let method;
  let irt = null;
  let finalSkillScores = skillScores;
  const tested = Object.keys(bandScores);
  if (answers.every((a) => a.cefr)) {
    // Rasch/1PL with fixed guessing + EAP (lib/algo/placement.js), same 0..1 skill contract.
    irt = scoreFixed({ targetLevel: level, answers: answers.map((a) => ({ id: a.id, skill: a.skill, cefr: a.cefr, correct: a.correct, ...(typeof a.b === 'number' ? { b: a.b } : {}) })) });
    method = 'irt_eap';
    estimatedLevel = irt.estimatedLevel;
    finalSkillScores = Object.fromEntries(Object.keys(skillScores).map((k) => [k, round2(irt.skillScores?.[k] ?? skillScores[k])]));
  } else if (tested.length) {
    method = 'cefr_bands';
    const passed = tested.filter((l) => bandScores[l].ratio >= PASS_RATIO);
    if (passed.length) estimatedLevel = passed[passed.length - 1]; // tested is in LEVELS order
    else {
      const lowest = LEVELS.indexOf(tested[0]);
      estimatedLevel = lowest > 0 ? LEVELS[lowest - 1] : 'pre-A1';
    }
  } else {
    // No per-question CEFR tags sent: fall back to overall ratio around the requested level.
    method = 'overall_ratio';
    const total = answers.length;
    const ratio = answers.filter((a) => a.correct).length / total;
    const b = bandsFor(level);
    estimatedLevel = ratio >= 0.8 && b.above ? b.above : ratio >= PASS_RATIO ? level : b.below || 'pre-A1';
  }

  const advice = [];
  const est = LEVELS.indexOf(estimatedLevel);
  const target = LEVELS.indexOf(level);
  if (est >= target) advice.push(`You look ready to work at ${level} for the ${exam}; use the roadmap to build exam technique.`);
  else advice.push(`Your self-check suggests about ${estimatedLevel}, below the ${level} target: allow more days, or spend the first phase consolidating ${estimatedLevel === 'pre-A1' ? 'A1' : LEVELS[est + 1]} basics.`);
  const sorted = Object.entries(finalSkillScores).sort((a, b) => a[1] - b[1]);
  for (const [skill, s] of sorted) {
    if (s < 0.5) advice.push(`Priority — ${skill} (${Math.round(s * 100)}%): ${SKILL_TIPS[skill]}.`);
  }
  for (const [skill, s] of sorted) {
    if (s >= 0.5 && s < 0.75) advice.push(`Keep practising ${skill} (${Math.round(s * 100)}%).`);
  }
  const strong = sorted.filter(([, s]) => s >= 0.75).map(([k]) => k);
  if (strong.length) advice.push(`Strong: ${strong.join(', ')} — keep them warm with short weekly reviews.`);
  if (answers.length < 6) advice.push('Very few answers — treat this estimate as rough.');

  return {
    status: 'ok',
    exam,
    level,
    skillScores: finalSkillScores,
    rawSkillScores: skillScores,
    bandScores,
    estimatedLevel,
    method,
    ...(irt ? { confidence: round2(irt.confidence), theta: round2(irt.theta), se: round2(irt.se) } : {}),
    weakSkills: sorted.filter(([, s]) => s < 0.5).map(([k]) => k),
    advice: advice.slice(0, 8),
    notice: SELF_CHECK_NOTICE
  };
}

/**
 * Item-calibration increments for one scored quiz (ARCHITECTURE.md §B.5): per answered item,
 * n += 1 and err += (correct − P(correct | θ̂, b)). Folded nightly into item_sets b values.
 * Pure; the route writes the result into calib_buckets/{shard}_{EXAM}_{LEVEL}. Null when nothing to record.
 */
export function calibrationDelta(scored, answers) {
  if (scored?.method !== 'irt_eap' || typeof scored.theta !== 'number') return null;
  const items = {};
  for (const a of answers || []) {
    if (!a || typeof a.itemKey !== 'string' || !/^[A-Za-z0-9_-]{1,40}$/.test(a.itemKey) || !a.cefr || typeof a.correct !== 'boolean') continue;
    const b = typeof a.b === 'number' && Number.isFinite(a.b) ? a.b : THETA[a.cefr] ?? 0;
    items[a.itemKey] = { n: 1, err: (a.correct ? 1 : 0) - pCorrect(scored.theta, b) };
  }
  return Object.keys(items).length ? items : null;
}
